export enum TenantProvisioningState {
  QUEUED = 'QUEUED',
  RESERVING = 'RESERVING',
  RUNNING = 'RUNNING',
  SUCCEEDED = 'SUCCEEDED',
  FAILED = 'FAILED',
}

export class TenantProvisioningStepDto {
  name!: string;
  state!: TenantProvisioningState;
  attempts!: number;
  lastError?: string;
  startedAt?: Date;
  completedAt?: Date;
}

export class CreateTenantAcceptedResponse {
  /**
   * Operation state. Public clients must make decisions from this field only.
   */
  status!: TenantProvisioningState;

  /**
   * Tenant lifecycle status from the approved admin projection, when known.
   */
  tenantStatus?: TenantStatus;

  /**
   * Canonical relative polling URL. Legacy /api, /api/v1, and /v1 aliases are
   * intentionally not part of the contract.
   */
  statusUrl!: string;

  retryAfterMs!: number;
  availableActions!: string[];

  /**
   * Per-step provisioning detail, ordered by step order.
   *
   * WHY: `status` alone collapses a twelve-step saga into one word. An operator
   * polling a FAILED run could see THAT it failed but never WHICH step failed or
   * WHY — the workflow already read the step rows on every poll and discarded
   * them. Always an array (never undefined) so clients render progress without
   * a presence check.
   */
  steps!: TenantProvisioningStepDto[];
}

