    if (this.authMode === 'file' && this.fileAuthEnabled) {
      try {
        await fs.access(this.passwordFilePath);
        this.logger.debug('Password file accessible');
      } catch {
        this.logger.warn('Password file not found, credentials will not be persisted');
      }
