    if (existing) {
      existing.retentionDays = retentionDays;
      const updated = await repo.save(existing);
      this.logger.log(
        `Updated retention policy ${updated.id}: ${retentionDays} days (tenant=${tenantId}, channel=${channelId ?? 'all'})`,
      );
      return updated;
    }

    const policy = repo.create({
